const questions=areas.flatMap((a,area)=>a.q.map(q=>({...q,area})));
const app=document.getElementById('app');let answers=Array(questions.length).fill(null),current=0,screen='intro';let advanceTimer=null, navigationTimer=null, navigating=false;
const blockIcons=['💬','🪞','🔥','🌳','🏆','⚡','🎯','👥','🔁','🧭'];
const num=n=>n.toFixed(1).replace('.',',');
const zone=n=>n<4?'Зона внимания':n<7.5?'В развитии':'Сильная сторона';
function moveTop(){window.scrollTo({top:0,behavior:'instant'});const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function intro(){screen='intro';app.innerHTML=`<section class="intro"><div><div class="eyebrow">Тест «Точка А»</div><h1>Твоя точка А<br>в искусстве<br><em>притяжения.</em></h1><p class="lead">Пойми, что помогает тебе знакомиться,<br>а что мешает строить близкие отношения.</p><div class="stats"><div class="stat"><b>10</b><span>сфер</span></div><div class="stat"><b>${questions.length}</b><span>вопросов</span></div><div class="stat"><b>~15</b><span>минут</span></div></div><button class="primary start" id="start">${answers.some(x=>x!==null)?'Продолжить тест':'Узнать свою точку А'}<span class="arrow">↗</span></button><p class="small-note">Отвечай честно. Здесь не нужно производить впечатление.</p></div><div class="art"><img class="cat" src="cat.png" alt="Кот в сапогах в шляпе с пером" width="450" height="470"><div class="art-label"><b>Маркиз</b>Твой проводник в естественном соблазнении</div><span class="art-tag">ХАРИЗМА • КОНТАКТ • БЛИЗОСТЬ</span></div></section><section class="areas"><div class="section-head"><h2>Что будем исследовать</h2><span>10 сфер твоей жизни и общения с девушками</span></div><div class="chips">${areas.map((a,i)=>`<div class="chip"><i>${String(i+1).padStart(2,'0')}</i>${a.n}</div>`).join('')}</div><p class="small-note">Для взрослых 18+. Авторский опросник для самоанализа, не психологическая диагностика. Ответы не отправляются на сервер и исчезнут после обновления страницы.</p></section>`;document.getElementById('start').onclick=()=>{question();moveTop()};}
function cancelAdvance(){if(advanceTimer!==null){clearTimeout(advanceTimer);advanceTimer=null;}}
function navigateQuestion(direction){if(navigating)return;cancelAdvance();if(direction<0&&current===0)return;navigating=true;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;const panel=app.querySelector('.quiz');if(panel)panel.classList.add(direction<0?'leave-back':'leave-forward');navigationTimer=setTimeout(()=>{navigationTimer=null;navigating=false;if(direction>0&&current===questions.length-1){results();}else{current+=direction;question(direction);}moveTop();},reduced?0:180);}
function advance(){cancelAdvance();if(answers[current]===null)return;navigateQuestion(1);}
function chooseAnswer(value){if(advanceTimer!==null||navigating)return;answers[current]=value;document.querySelectorAll('[data-choice]').forEach(b=>{b.setAttribute('aria-pressed',Number(b.dataset.choice)===value?'true':'false');b.disabled=true;});advanceTimer=setTimeout(advance,220);}
function question(direction=1){cancelAdvance();screen='quiz';const q=questions[current],answered=answers.filter(x=>x!==null).length,blockStart=areas.slice(0,q.area).reduce((n,a)=>n+a.q.length,0),inBlock=current-blockStart+1;app.innerHTML=`<section class="quiz ${direction<0?'enter-back':'enter-forward'}"><div class="quiz-top"><button class="text-button" id="home">← К началу</button><span>Вопрос ${current+1} <span style="color:#62605c">/ ${questions.length}</span></span></div><div class="track" role="progressbar" aria-label="Пройдено вопросов" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${answered}"><span style="width:${answered/questions.length*100}%"></span></div><div class="block-banner" aria-label="Текущий блок: ${areas[q.area].n}"><span class="block-icon" aria-hidden="true">${blockIcons[q.area]}</span><div class="block-title"><span class="block-kicker">БЛОК ${q.area+1} ИЗ ${areas.length}</span><h2>${areas[q.area].n}</h2></div><span class="block-count">${inBlock} / ${areas[q.area].q.length}<small>вопрос в блоке</small></span><div class="block-steps" aria-hidden="true">${areas[q.area].q.map((_,i)=>`<span class="${i<inBlock-1?'done':i===inBlock-1?'active':''}"></span>`).join('')}</div></div><div class="question-panel"><h1>${q.text}</h1><p class="hint">Выбери один ответ — следующий вопрос откроется автоматически.</p><div class="options" role="group" aria-label="Выбери один ответ">${q.options.map((o,i)=>`<button class="option" data-choice="${i}" aria-pressed="${answers[current]===i}"><span class="radio" aria-hidden="true"></span>${o}</button>`).join('')}</div></div><div class="quiz-nav"><button class="text-button" id="back" ${current===0?'disabled':''}>← Назад</button>${answers[current]!==null?`<button class="text-button" id="next">${current===questions.length-1?'К результату':'К следующему вопросу'} →</button>`:''}</div><p class="small-note">Чтобы изменить ответ, вернись назад и выбери другой вариант.</p></section>`;document.getElementById('home').onclick=()=>{cancelAdvance();clearTimeout(navigationTimer);navigationTimer=null;navigating=false;intro();moveTop()};document.getElementById('back').onclick=()=>navigateQuestion(-1);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseAnswer(Number(b.dataset.choice)));const next=document.getElementById('next');if(next)next.onclick=advance;}
function calculate(values){let offset=0;return areas.map((a,i)=>{const part=values.slice(offset,offset+a.q.length);offset+=a.q.length;return {...a,i,score:part.reduce((s,x)=>s+x*2.5,0)/a.q.length};});}
function radar(scores){const cx=250,cy=230,r=151;const pt=(i,value)=>{let angle=-Math.PI/2+i*Math.PI/5;return [cx+Math.cos(angle)*r*value/10,cy+Math.sin(angle)*r*value/10]};const points=v=>scores.map((s,i)=>pt(i,v).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 500 470" role="img" aria-label="Колесо самооценки по десяти сферам. Точные баллы приведены ниже."><title>Твоя точка А: колесо 10 сфер</title>${[2,4,6,8,10].map(v=>`<polygon points="${points(v)}" fill="none" stroke="${v===10?'#4b443c':'#2d2b28'}"/>`).join('')}${scores.map((s,i)=>{let p=pt(i,10);return `<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}" stroke="#302d28"/>`}).join('')}<polygon points="${scores.map((s,i)=>pt(i,s.score).join(',')).join(' ')}" fill="#ff792b" fill-opacity=".17" stroke="#ff792b" stroke-width="2.5"/>${scores.map((s,i)=>{let p=pt(i,s.score),l=pt(i,12.5);return `<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#ff792b"/><text x="${l[0]}" y="${l[1]-5}" text-anchor="middle" fill="#aaa39a" font-size="12" font-family="Manrope,Arial">${s.short}</text><text x="${l[0]}" y="${l[1]+13}" text-anchor="middle" fill="#f4f1ec" font-size="14" font-weight="700" font-family="Manrope,Arial">${num(s.score)}</text>`}).join('')}</svg>`;}
function results(){screen='results';const scores=calculate(answers),avg=scores.reduce((s,a)=>s+a.score,0)/10,sorted=[...scores].sort((a,b)=>a.score-b.score),weak=sorted.slice(0,3),strong=[...scores].sort((a,b)=>b.score-a.score).slice(0,3),focus=weak[0],equal=scores.every(s=>s.score===scores[0].score);const heading=avg<4?'Есть с чего начать.':avg<7.5?'Твоя база уже есть.':'У тебя сильная база.';app.innerHTML=`<section class="results"><div class="result-heading"><div class="eyebrow">Твой личный разбор</div><h1>Вот твоя точка А.</h1><p>Твоя самооценка по 10 сферам: от реальных знакомств до привычек и страхов.</p></div><div class="overview"><div class="radar-card">${radar(scores)}</div><div class="score-card"><span class="score-label">Средняя самооценка по 10 сферам</span><div class="score-big">${num(avg)} <small>/ 10</small></div><h2>${heading}</h2><p>${avg<4?'Выбери один небольшой шаг и практикуй его без спешки. Отсутствие опыта — тоже нормальная точка старта.':avg<7.5?'В одних ситуациях ты чувствуешь себя свободно, в других пока не хватает практики. Начни с одной сферы, которую хочешь укрепить.':'Сохраняй то, что уже получается, и удели внимание менее привычным ситуациям. Ориентируйся и на обратную связь другого человека.'}</p></div></div><section class="all-scores"><h2>Все 10 сфер <span style="color:#827d76;font-size:12px;font-weight:500">/ твоя карта</span></h2>${scores.map(s=>`<div class="score-row" style="--score-hue:${Math.max(0,Math.min(10,s.score))*12}"><div class="score-row-top"><span class="index">${String(s.i+1).padStart(2,'0')}</span><span>${s.n}</span><span class="zone">${zone(s.score)}</span><b>${num(s.score)}</b></div><div class="bar"><span style="width:${s.score*10}%"></span></div></div>`).join('')}</section><div class="insights"><section class="insight growth"><h3>↗ ${equal?'Сферы для практики':'Точки роста'}</h3>${weak.map(s=>`<div class="mini-row"><span>${s.n}</span><b>${num(s.score)}</b></div>`).join('')}</section><section class="insight strength"><h3>✦ ${equal?'Навыки с тем же баллом':strong[0].score<7.5?'Твоя относительная опора':'Сильные стороны'}</h3>${(equal?scores.slice(3,6):strong).map(s=>`<div class="mini-row"><span>${s.n}</span><b>${num(s.score)}</b></div>`).join('')}</section></div><section class="advice"><div class="eyebrow">Твой следующий шаг</div><h2>${equal?'Начни с фактов':focus.n+' — '+num(focus.score)+' / 10'}</h2><p>${equal?'Все сферы получили одинаковый балл, поэтому явного лидера или отстающей сферы нет. Разбор фактов — один из возможных стартов. ':''}${focus.tip}</p><p class="practice"><strong>Практика на ближайшую неделю</strong><br>${focus.task}</p><p class="small-note">Баллы отражают твои ответы, а не гарантируют результат в отношениях. ${equal?'': 'При одинаковых баллах сфер порядок условный.'} Взаимный интерес, уважение и согласие важны при любом результате.</p></section><div class="signoff"><img src="cat.png" alt="Кот в сапогах" width="110" height="135"><div><h3>Точка А — только начало.</h3><p>Теперь ты знаешь, с чего начать. Следующий шаг — за тобой.</p><span class="signature">ТВОЙ МАРКИЗ</span></div></div><button class="text-button" id="review">← Вернуться к ответам</button><button class="restart" id="restart">Пройти тест заново ↻</button><p class="small-note">Сохрани результат скриншотом для разбора с наставником. После обновления страницы ответы исчезнут.</p></section>`;document.getElementById('review').onclick=()=>{current=questions.length-1;question();moveTop()};document.getElementById('restart').onclick=()=>{answers=Array(questions.length).fill(null);current=0;intro();moveTop()};}
intro();
